import { useState } from 'react';
import { Link } from 'react-router-dom';
import { Popover } from 'radix-ui';
import { AnimatePresence, motion } from 'motion/react';
import { Bell, BellOff, Info, Lightbulb, type LucideIcon } from 'lucide-react';
import { Button, EmptyState, IconButton } from '@/components/ui';
import { cn } from '@/lib/cn';
import { transition } from '@/lib/motion';

interface Notice {
  id: string;
  icon: LucideIcon;
  title: string;
  body: string;
  href?: string;
  read: boolean;
}

/**
 * Phase 1 only holds local product notices generated by this website.
 * Broker, connector and AI alerts will arrive here once those services exist.
 */
const initialNotices: Notice[] = [
  {
    id: 'welcome',
    icon: Info,
    title: 'Welcome to the TradePilot preview',
    body: 'This version is a design preview. Nothing is connected to MT5, a broker or an AI service yet.',
    read: false,
  },
  {
    id: 'next-step',
    icon: Lightbulb,
    title: 'Suggested first step',
    body: 'Read how the Windows connector links this website to MetaTrader 5.',
    href: '/connections',
    read: false,
  },
];

export function NotificationPopover() {
  const [notices, setNotices] = useState(initialNotices);
  const unread = notices.filter((n) => !n.read).length;

  return (
    <Popover.Root>
      <Popover.Trigger asChild>
        <IconButton
          label={unread ? `Notifications, ${unread} unread` : 'Notifications'}
          tooltip="Notifications"
          icon={
            <span className="relative flex">
              <Bell />
              {unread > 0 && (
                <span className="bg-accent ring-canvas absolute -top-0.5 -right-0.5 size-2 rounded-full ring-2" aria-hidden />
              )}
            </span>
          }
        />
      </Popover.Trigger>
      <Popover.Portal>
        <Popover.Content
          align="end"
          sideOffset={8}
          collisionPadding={12}
          style={{ zIndex: 'var(--z-popover)' }}
          className="bg-raised border-line shadow-lg data-[state=open]:animate-fade-in w-[min(24rem,calc(100vw-24px))] overflow-hidden rounded-xl border"
        >
          <div className="border-line-soft flex items-center justify-between gap-2 border-b px-4 py-3">
            <div>
              <h2 className="text-fg text-sm font-semibold">Notifications</h2>
              <p className="text-fg-3 text-xs">Local notices from this website only</p>
            </div>
            {notices.length > 0 && (
              <Button
                variant="ghost"
                size="sm"
                disabled={unread === 0}
                onClick={() => setNotices((n) => n.map((x) => ({ ...x, read: true })))}
              >
                Mark all read
              </Button>
            )}
          </div>
          {notices.length === 0 ? (
            <EmptyState
              size="sm"
              icon={BellOff}
              title="You're all caught up"
              description="Alerts about backtests, the MT5 connector and AI research will appear here once those services are connected."
            />
          ) : (
            <ul className="max-h-80 overflow-y-auto">
              <AnimatePresence initial={false}>
                {notices.map((n) => {
                  const Icon = n.icon;
                  return (
                    <motion.li
                      key={n.id}
                      layout
                      exit={{ opacity: 0, height: 0, transition: transition.fast }}
                      className="border-line-soft border-b last:border-0"
                    >
                      <div className="flex gap-3 px-4 py-3">
                        <Icon className={cn('mt-0.5 size-4 shrink-0', n.read ? 'text-fg-3' : 'text-accent')} aria-hidden />
                        <div className="min-w-0 flex-1">
                          <p className={cn('text-sm', n.read ? 'text-fg-2' : 'text-fg font-medium')}>
                            {n.title}
                            {!n.read && <span className="sr-only"> (unread)</span>}
                          </p>
                          <p className="text-fg-3 mt-0.5 text-sm leading-relaxed">{n.body}</p>
                          <div className="mt-2 flex gap-3 text-xs">
                            {n.href && (
                              <Popover.Close asChild>
                                <Link to={n.href} className="text-accent font-medium hover:underline">
                                  Open
                                </Link>
                              </Popover.Close>
                            )}
                            <button
                              type="button"
                              className="text-fg-3 hover:text-fg-2"
                              onClick={() => setNotices((all) => all.filter((x) => x.id !== n.id))}
                            >
                              Dismiss
                            </button>
                          </div>
                        </div>
                      </div>
                    </motion.li>
                  );
                })}
              </AnimatePresence>
            </ul>
          )}
        </Popover.Content>
      </Popover.Portal>
    </Popover.Root>
  );
}
